    "recordKey": "https://ted.europa.eu/de/notice/-/detail/566424-2026",
    "portal": "TED",
    "suchbegriff": "CPV 75112100-5 - Verwaltungsentwicklung",
    "titel": "Deutschland – Mit Entwicklungsprojekten verbundene Verwaltungsdienstleistungen – Unterstützung im Kundenservice",
    "auftraggeber": "Stadtwerke Lübeck Gruppe GmbH",
